import json
import os
import uuid
from typing import List, Dict, Any, Optional

TEMPLATES_FILE = "data/parser_templates.json"

class TemplateManager:
    @staticmethod
    def _load_templates() -> Dict[str, Any]:
        if not os.path.exists(TEMPLATES_FILE):
            return {}
        try:
            with open(TEMPLATES_FILE, 'r') as f:
                return json.load(f)
        except Exception:
            return {}

    @staticmethod
    def _save_templates(templates: Dict[str, Any]):
        os.makedirs(os.path.dirname(TEMPLATES_FILE), exist_ok=True)
        with open(TEMPLATES_FILE, 'w') as f:
            json.dump(templates, f, indent=2)

    @classmethod
    def get_all(cls) -> List[Dict[str, Any]]:
        templates = cls._load_templates()
        return list(templates.values())

    @classmethod
    def get_by_id(cls, template_id: str) -> Optional[Dict[str, Any]]:
        templates = cls._load_templates()
        return templates.get(template_id)

    @classmethod
    def save(cls, template_data: Dict[str, Any]) -> Dict[str, Any]:
        templates = cls._load_templates()

        if "id" not in template_data or not template_data["id"]:
            template_data["id"] = str(uuid.uuid4())

        # Ensure timestamp?
        # template_data["updated_at"] = ...

        templates[template_data["id"]] = template_data
        cls._save_templates(templates)
        return template_data

    @classmethod
    def delete(cls, template_id: str) -> bool:
        templates = cls._load_templates()
        if template_id in templates:
            del templates[template_id]
            cls._save_templates(templates)
            return True
        return False

from abc import ABC, abstractmethod
import pandas as pd
import numpy as np
import datetime
from typing import List, Dict, Any

class BaseBankParser(ABC):
    """
    Abstract Base Class for all bank statement parsers.
    Ensures that every module returns data in the Universal Financial Format.
    """

    @property
    @abstractmethod
    def bank_name(self) -> str:
        pass

    @abstractmethod
    def parse(self, file_path: str) -> List[Dict[str, Any]]:
        """
        Parses the file and returns a list of dictionaries 
        matching the Transaction database model.
        """
        pass

    def standardize_dataframe(self, df: pd.DataFrame, mapping: Dict[str, str]) -> pd.DataFrame:
        """Helper to rename columns and ensure UFF (Universal Financial Format)."""
        return df.rename(columns=mapping)

    def sanitize_for_json(self, data: Dict[str, Any]) -> Dict[str, Any]:
        """
        Recursively converts dates, timestamps and NaNs into JSON-serializable formats.
        """
        sanitized = {}
        for key, value in data.items():
            # Check for various date/time types using the datetime module safely
            if isinstance(value, (datetime.datetime, datetime.date, pd.Timestamp)):
                sanitized[key] = value.isoformat()
            elif isinstance(value, float) and (np.isnan(value) or np.isinf(value)):
                sanitized[key] = None
            elif isinstance(value, dict):
                sanitized[key] = self.sanitize_for_json(value)
            elif isinstance(value, list):
                sanitized[key] = [
                    self.sanitize_for_json(v) if isinstance(v, dict) else v 
                    for v in value
                ]
            else:
                sanitized[key] = value
        return sanitized

