import React, { useState, useRef, useEffect } from 'react';
import { 
  X, Save, Play, Plus, Trash2, Settings, FileText, 
  Table as TableIcon, ChevronLeft, ChevronRight, 
  MousePointer2, List as ListIcon, Edit, Layers,
  CheckCircle2, AlertCircle, ArrowUp, ArrowDown
} from 'lucide-react';
import axios from 'axios';

interface ParserBuilderProps {
  onClose: () => void;
  apiBaseUrl: string;
}

type RegionType = 'table' | 'text' | 'key_value';
type ColumnType = 'string' | 'currency' | 'float' | 'date';

interface ColumnDef {
  x: number; 
  name: string;
  type: ColumnType;
}

interface Region {
  id: string;
  x: number; // %
  y: number; // %
  w: number; // %
  h: number; // %
  type: RegionType;
  name: string;
  key_label?: string; // For key_value type
  columns?: ColumnDef[];
}

export const ParserBuilder: React.FC<ParserBuilderProps> = ({ onClose, apiBaseUrl }) => {
  // View State
  const [view, setView] = useState<'list' | 'edit'>('list');
  const [templates, setTemplates] = useState<any[]>([]);

  // Template State
  const [templateId, setTemplateId] = useState<string | null>(null);
  const [templateName, setTemplateName] = useState('');

  // Builder State
  const [regions, setRegions] = useState<Region[]>([]);
  const [selectedRegionId, setSelectedRegionId] = useState<string | null>(null);
  const [pageStrategy, setPageStrategy] = useState({
    mode: 'all',
    regex: '',
    stopCondition: ''
  });

  // Page Navigation
  const [currentPage, setCurrentPage] = useState(0);
  const [pageCount, setPageCount] = useState(1);

  // Data Preview
  const [testFile, setTestFile] = useState<File | null>(null);
  const [previewData, setPreviewData] = useState<any>({});
  const [debugImage, setDebugImage] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);

  // Drawing State
  const canvasRef = useRef<HTMLDivElement>(null);
  const [isDrawing, setIsDrawing] = useState(false);
  const [startPos, setStartPos] = useState({ x: 0, y: 0 });
  const [currentRect, setCurrentRect] = useState({ x: 0, y: 0, w: 0, h: 0 });

  // -------------------------------------------------------------------------
  // Template Management
  // -------------------------------------------------------------------------
  useEffect(() => {
      if (view === 'list') fetchTemplates();
  }, [view]);

  const fetchTemplates = async () => {
      try {
          const res = await axios.get(`${apiBaseUrl}/api/parsers/templates`);
          setTemplates(res.data);
      } catch (err) {
          console.error("Failed to load templates");
      }
  };

  const handleSaveTemplate = async () => {
      if (!templateName.trim()) {
          alert("Please name your template.");
          return;
      }

      try {
          const payload = {
              id: templateId,
              name: templateName,
              page_strategy: pageStrategy,
              regions: regions
          };

          await axios.post(`${apiBaseUrl}/api/parsers/templates`, payload);
          alert("Template saved!");
          fetchTemplates();
          setView('list');
      } catch (error) {
          alert("Failed to save template.");
      }
  };

  const handleEditTemplate = (tmpl: any) => {
      setTemplateId(tmpl.id);
      setTemplateName(tmpl.name);
      setPageStrategy(tmpl.page_strategy || { mode: 'all', regex: '', stopCondition: '' });
      setRegions(tmpl.regions || []);
      setTestFile(null);
      setDebugImage(null);
      setPreviewData({});
      setCurrentPage(0);
      setView('edit');
  };

  const handleDeleteTemplate = async (id: string) => {
      if (!window.confirm("Are you sure?")) return;
      try {
          await axios.delete(`${apiBaseUrl}/api/parsers/templates/${id}`);
          fetchTemplates();
      } catch (err) {
          alert("Delete failed.");
      }
  };

  const handleNewTemplate = () => {
      setTemplateId(null);
      setTemplateName("New Template");
      setRegions([]);
      setPageStrategy({ mode: 'all', regex: '', stopCondition: '' });
      setTestFile(null);
      setDebugImage(null);
      setPreviewData({});
      setView('edit');
  };

  // -------------------------------------------------------------------------
  // Drawing Logic
  // -------------------------------------------------------------------------
  const handleMouseDown = (e: React.MouseEvent) => {
    if (!canvasRef.current) return;
    if ((e.target as HTMLElement).closest('.region-box')) return;

    const rect = canvasRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    setIsDrawing(true);
    setStartPos({ x, y });
    setCurrentRect({ x, y, w: 0, h: 0 });
    setSelectedRegionId(null); 
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDrawing || !canvasRef.current) return;
    const rect = canvasRef.current.getBoundingClientRect();
    const currentX = e.clientX - rect.left;
    const currentY = e.clientY - rect.top;

    const width = currentX - startPos.x;
    const height = currentY - startPos.y;

    setCurrentRect({
        x: width > 0 ? startPos.x : currentX,
        y: height > 0 ? startPos.y : currentY,
        w: Math.abs(width),
        h: Math.abs(height)
    });
  };

  const handleMouseUp = () => {
    if (!isDrawing || !canvasRef.current) return;
    setIsDrawing(false);

    if (currentRect.w < 10 || currentRect.h < 10) {
        setCurrentRect({ x: 0, y: 0, w: 0, h: 0 });
        return;
    }

    const containerW = canvasRef.current.offsetWidth;
    const containerH = canvasRef.current.offsetHeight;

    const newRegion: Region = {
        id: Math.random().toString(36).substr(2, 9),
        x: (currentRect.x / containerW) * 100,
        y: (currentRect.y / containerH) * 100,
        w: (currentRect.w / containerW) * 100,
        h: (currentRect.h / containerH) * 100,
        type: 'text',
        name: `Region ${regions.length + 1}`,
        columns: []
    };

    setRegions([...regions, newRegion]);
    setSelectedRegionId(newRegion.id);
    setCurrentRect({ x: 0, y: 0, w: 0, h: 0 });
  };

  const handleMouseLeave = () => {
      if (isDrawing) {
          setIsDrawing(false);
          setCurrentRect({ x: 0, y: 0, w: 0, h: 0 });
      }
  };

  // -------------------------------------------------------------------------
  // API Actions
  // -------------------------------------------------------------------------
  const handleTestExtraction = async () => {
    if (!testFile) {
        alert("Please upload a sample file first.");
        return;
    }

    setIsLoading(true);
    const formData = new FormData();
    formData.append('file', testFile);
    formData.append('page', currentPage.toString());
    formData.append('config', JSON.stringify({
        regions,
        page_strategy: pageStrategy
    }));

    try {
        const res = await axios.post(`${apiBaseUrl}/api/parsers/preview`, formData);
        setPreviewData(res.data.extracted_data);
        setDebugImage(res.data.debug_image);
        if (res.data.page_count) setPageCount(res.data.page_count);
    } catch (error) {
        alert("Extraction failed");
    } finally {
        setIsLoading(false);
    }
  };

  // -------------------------------------------------------------------------
  // Region Editing Logic
  // -------------------------------------------------------------------------
  const selectedRegion = regions.find(r => r.id === selectedRegionId);

  const updateRegion = (field: keyof Region, value: any) => {
      if (!selectedRegion) return;
      const updated = regions.map(r => r.id === selectedRegionId ? { ...r, [field]: value } : r);
      setRegions(updated);
  };

  const deleteRegion = (id?: string) => {
      const targetId = id || selectedRegionId;
      if (!targetId) return;
      setRegions(regions.filter(r => r.id !== targetId));
      if (targetId === selectedRegionId) setSelectedRegionId(null);
  };

  const moveRegion = (index: number, direction: 'up' | 'down') => {
      const newRegions = [...regions];
      if (direction === 'up' && index > 0) {
          [newRegions[index], newRegions[index - 1]] = [newRegions[index - 1], newRegions[index]];
      } else if (direction === 'down' && index < newRegions.length - 1) {
          [newRegions[index], newRegions[index + 1]] = [newRegions[index + 1], newRegions[index]];
      }
      setRegions(newRegions);
  };

  const addColumn = () => {
      if (!selectedRegion) return;
      const cols = selectedRegion.columns || [];
      const newCol: ColumnDef = { x: 50, name: `Col ${cols.length + 1}`, type: 'string' };
      updateRegion('columns', [...cols, newCol]);
  };

  const updateColumn = (idx: number, field: keyof ColumnDef, val: any) => {
      if (!selectedRegion?.columns) return;
      const newCols = [...selectedRegion.columns];
      newCols[idx] = { ...newCols[idx], [field]: val };
      updateRegion('columns', newCols);
  };

  const removeColumn = (idx: number) => {
      if (!selectedRegion?.columns) return;
      updateRegion('columns', selectedRegion.columns.filter((_, i) => i !== idx));
  };


  return (
    <div className="fixed inset-0 bg-canvas z-50 overflow-y-auto font-sans">
      <div className="max-w-7xl mx-auto p-8">

        {/* Main Header */}
        <div className="flex justify-between items-center mb-8">
          <div className="flex items-center gap-4">
            {view === 'edit' && (
                <button onClick={() => setView('list')} className="p-2 bg-white rounded-full shadow-sm hover:bg-slate-50 transition-colors">
                    <ChevronLeft size={20} />
                </button>
            )}
            <div>
                <h1 className="text-3xl font-bold tracking-tight text-slate-900">Parser Builder</h1>
                <p className="text-slate-500 font-medium">
                    {view === 'list' ? 'Manage your extraction templates.' : 'Design and test your extraction layout.'}
                </p>
            </div>
          </div>
          <div className="flex gap-4">
            {view === 'edit' && (
                <div className="flex items-center gap-3 bg-white px-4 py-2 rounded-xl shadow-sm border border-slate-100">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Template Name</span>
                    <input 
                        type="text" 
                        value={templateName}
                        onChange={(e) => setTemplateName(e.target.value)}
                        className="font-bold text-slate-800 outline-none w-48 bg-transparent"
                        placeholder="e.g. My Bank Statement"
                    />
                </div>
            )}
            {view === 'edit' && (
                <button onClick={handleSaveTemplate} className="flex items-center gap-2 px-6 py-2 bg-slate-900 text-white rounded-xl font-bold hover:scale-105 transition-transform shadow-lg">
                    <Save size={18} /> Save Template
                </button>
            )}
            <button onClick={onClose} className="p-2 hover:bg-slate-200 rounded-full transition-colors">
              <X size={24} />
            </button>
          </div>
        </div>

        {/* LIST VIEW */}
        {view === 'list' && (
            <div className="bg-surface rounded-[40px] shadow-soft p-10 border border-slate-100">
                <div className="flex justify-between items-center mb-10">
                    <div>
                        <h3 className="text-2xl font-black tracking-tight">Saved Templates</h3>
                        <p className="text-slate-400 text-sm font-medium">Select a template to edit or create a new one.</p>
                    </div>
                    <button onClick={handleNewTemplate} className="flex items-center gap-2 px-8 py-4 bg-primary-start text-white font-black rounded-2xl hover:bg-primary-end transition-all shadow-brand hover:scale-105">
                        <Plus size={20} /> Create New Template
                    </button>
                </div>

                {templates.length === 0 ? (
                    <div className="text-center py-24 bg-slate-50 rounded-[32px] border-2 border-dashed border-slate-200">
                        <ListIcon size={64} className="mx-auto text-slate-200 mb-6" />
                        <p className="text-slate-500 font-bold text-lg">No templates found yet.</p>
                        <p className="text-slate-400 text-sm mt-1">Templates allow you to automate data entry from complex PDFs.</p>
                    </div>
                ) : (
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                        {templates.map(t => (
                            <div key={t.id} className="bg-white p-8 rounded-[32px] border border-slate-100 shadow-sm hover:shadow-xl transition-all group relative overflow-hidden">
                                <div className="absolute top-0 right-0 w-32 h-32 bg-slate-50 rounded-full -mr-16 -mt-16 group-hover:bg-primary-start/5 transition-colors"></div>
                                <div className="relative z-10">
                                    <div className="flex justify-between items-start mb-6">
                                        <div className="p-4 bg-slate-50 rounded-2xl text-slate-400 group-hover:text-primary-start group-hover:bg-primary-start/10 transition-colors">
                                            <FileText size={28} />
                                        </div>
                                        <div className="flex gap-2">
                                            <button onClick={() => handleEditTemplate(t)} className="p-2 text-slate-400 hover:text-emerald-600 hover:bg-emerald-50 rounded-lg transition-colors"><Edit size={18} /></button>
                                            <button onClick={() => handleDeleteTemplate(t.id)} className="p-2 text-slate-400 hover:text-rose-600 hover:bg-rose-50 rounded-lg transition-colors"><Trash2 size={18} /></button>
                                        </div>
                                    </div>
                                    <h4 className="font-black text-xl mb-2 text-slate-800">{t.name}</h4>
                                    <div className="flex flex-wrap gap-2 mt-4">
                                        <span className="text-[10px] font-black uppercase tracking-widest bg-slate-100 px-3 py-1.5 rounded-full text-slate-500">{t.regions?.length || 0} Zones</span>
                                        <span className="text-[10px] font-black uppercase tracking-widest bg-emerald-50 px-3 py-1.5 rounded-full text-emerald-600">{t.page_strategy?.mode}</span>
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                )}
            </div>
        )}

        {/* EDITOR VIEW */}
        {view === 'edit' && (
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 items-start">
            {/* Controls Sidebar */}
            <div className="lg:col-span-1 space-y-6">

                {/* 0. File Upload & Page Nav */}
                <div className="bg-surface p-6 rounded-3xl shadow-soft border border-slate-100">
                    <h3 className="font-black text-xs uppercase tracking-widest text-slate-400 mb-4 flex items-center gap-2"><FileText size={14} /> Sample Source</h3>
                    <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
                        <input 
                            type="file" 
                            id="sample-upload"
                            className="hidden"
                            onChange={(e) => {
                                setTestFile(e.target.files ? e.target.files[0] : null);
                                setDebugImage(null);
                            }}
                        />
                        <label htmlFor="sample-upload" className="cursor-pointer block text-center">
                            <p className="text-sm font-bold text-slate-700">{testFile ? testFile.name : 'Choose PDF file...'}</p>
                            <p className="text-[10px] text-slate-400 mt-1 uppercase font-black">Click to change</p>
                        </label>
                    </div>

                    {testFile && (
                        <div className="flex items-center justify-between mt-4 bg-slate-900 text-white p-2 rounded-2xl shadow-lg">
                            <button 
                                onClick={() => setCurrentPage(Math.max(0, currentPage - 1))}
                                disabled={currentPage === 0}
                                className="p-2 hover:bg-white/10 rounded-xl disabled:opacity-20 transition-colors"
                            >
                                <ChevronLeft size={20} />
                            </button>
                            <div className="text-center">
                                <p className="text-[9px] font-black uppercase tracking-tighter opacity-60">Viewing Page</p>
                                <p className="text-sm font-black font-mono">{currentPage + 1} / {pageCount}</p>
                            </div>
                            <button 
                                onClick={() => setCurrentPage(Math.min(pageCount - 1, currentPage + 1))}
                                disabled={currentPage >= pageCount - 1}
                                className="p-2 hover:bg-white/10 rounded-xl disabled:opacity-20 transition-colors"
                            >
                                <ChevronRight size={20} />
                            </button>
                        </div>
                    )}

                    <button 
                        onClick={handleTestExtraction}
                        disabled={!testFile || isLoading}
                        className={`w-full mt-4 py-4 font-black rounded-2xl flex items-center justify-center gap-2 transition-all shadow-brand ${!testFile ? 'bg-slate-100 text-slate-300' : 'bg-primary-start text-white hover:scale-[1.02]'}`}
                    >
                        {isLoading ? <span className="animate-spin text-lg">⟳</span> : <Play size={18} fill="currentColor" />} 
                        {isLoading ? 'Processing...' : 'Run Extraction'}
                    </button>
                </div>

                {/* Sidebar Context Switcher */}
                <div className="space-y-6">
                    {/* Region List (Always visible if edit) */}
                    <div className="bg-surface p-6 rounded-3xl shadow-soft border border-slate-100">
                        <div className="flex justify-between items-center mb-4">
                            <h3 className="font-black text-xs uppercase tracking-widest text-slate-400 flex items-center gap-2"><Layers size={14} /> Layout Zones</h3>
                            <span className="bg-slate-100 text-slate-500 text-[10px] font-bold px-2 py-0.5 rounded-full">{regions.length}</span>
                        </div>
                        <div className="space-y-2 max-h-48 overflow-y-auto pr-1 text-left">
                            {regions.map(r => (
                                <div 
                                    key={r.id} 
                                    onClick={() => setSelectedRegionId(r.id)}
                                    className={`flex items-center justify-between p-3 rounded-xl border transition-all cursor-pointer ${selectedRegionId === r.id ? 'bg-primary-start/5 border-primary-start/30 shadow-sm' : 'bg-white border-slate-100 hover:border-slate-300'}`}
                                >
                                    <div className="flex items-center gap-3">
                                        <div className={`w-2 h-2 rounded-full ${r.type === 'table' ? 'bg-emerald-500' : r.type === 'text' ? 'bg-rose-500' : 'bg-blue-500'}`}></div>
                                        <span className={`text-xs font-bold ${selectedRegionId === r.id ? 'text-slate-900' : 'text-slate-600'}`}>{r.name}</span>
                                    </div>
                                    <button onClick={(e) => { e.stopPropagation(); deleteRegion(r.id); }} className="text-slate-300 hover:text-rose-500 transition-colors"><Trash2 size={14} /></button>
                                </div>
                            ))}
                            {regions.length === 0 && <p className="text-center py-4 text-xs italic text-slate-400">No zones defined. Drag on canvas to add.</p>}
                        </div>
                    </div>

                    {/* Editor Panel */}
                    {selectedRegion ? (
                        <div className="bg-surface p-6 rounded-3xl shadow-soft border-2 border-primary-start animate-in slide-in-from-left-2 text-left">
                            <div className="flex justify-between items-center mb-6">
                                <h3 className="font-black text-xs uppercase tracking-widest text-primary-start flex items-center gap-2">
                                    <MousePointer2 size={14} /> Configure Zone
                                </h3>
                                <button onClick={() => setSelectedRegionId(null)} className="text-slate-400 hover:text-slate-600"><X size={16} /></button>
                            </div>

                            <div className="space-y-5">
                                <div>
                                    <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Zone Label</label>
                                    <input 
                                        type="text" 
                                        value={selectedRegion.name} 
                                        onChange={(e) => updateRegion('name', e.target.value)}
                                        className="w-full mt-1 bg-slate-50 border border-slate-200 rounded-xl p-3 text-sm font-bold outline-none focus:border-primary-start transition-colors"
                                    />
                                </div>
                                <div>
                                    <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Extraction Mode</label>
                                    <select 
                                        value={selectedRegion.type} 
                                        onChange={(e) => updateRegion('type', e.target.value)}
                                        className="w-full mt-1 bg-slate-50 border border-slate-200 rounded-xl p-3 text-sm font-bold outline-none"
                                    >
                                        <option value="text">📄 Raw Text Block</option>
                                        <option value="table">Structured Table</option>
                                        <option value="key_value">Key-Value Pairs</option>
                                    </select>
                                </div>

                                {selectedRegion.type === 'table' && (
                                    <div className="border-t border-slate-100 pt-5">
                                        <div className="flex justify-between items-center mb-3">
                                            <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Column Definitions</label>
                                            <button onClick={addColumn} className="text-[10px] font-black text-emerald-600 uppercase tracking-tighter hover:underline">+ Add New</button>
                                        </div>
                                        <div className="space-y-3 max-h-60 overflow-y-auto pr-1">
                                            {(selectedRegion.columns || []).map((col, idx) => (
                                                <div key={idx} className="bg-white p-3 rounded-2xl border border-slate-100 shadow-sm space-y-2 group">
                                                    <div className="flex gap-2">
                                                        <input 
                                                            type="number" 
                                                            value={col.x} 
                                                            onChange={(e) => updateColumn(idx, 'x', parseInt(e.target.value))} 
                                                            className="w-16 bg-slate-50 border border-slate-100 rounded-lg p-1.5 text-[10px] font-mono font-bold"
                                                            placeholder="X-Pos"
                                                        />
                                                        <input 
                                                            type="text" 
                                                            value={col.name} 
                                                            onChange={(e) => updateColumn(idx, 'name', e.target.value)} 
                                                            className="flex-1 bg-slate-50 border border-slate-100 rounded-lg p-1.5 text-[10px] font-bold"
                                                            placeholder="Col Name"
                                                        />
                                                        <button onClick={() => removeColumn(idx)} className="text-slate-300 hover:text-rose-500"><Trash2 size={14} /></button>
                                                    </div>
                                                    <select
                                                        value={col.type}
                                                        onChange={(e) => updateColumn(idx, 'type', e.target.value)}
                                                        className="w-full bg-slate-50 border border-slate-100 rounded-lg p-1.5 text-[9px] font-black uppercase tracking-widest text-slate-500"
                                                    >
                                                        <option value="string">Text String</option>
                                                        <option value="currency">Currency (€)</option>
                                                        <option value="float">Number (Float)</option>
                                                        <option value="date">Date</option>
                                                    </select>
                                                </div>
                                            ))}
                                        </div>
                                    </div>
                                )}
                            </div>
                        </div>
                    ) : (
                        <div className="bg-surface p-6 rounded-3xl shadow-soft border border-slate-100 text-left">
                            <h3 className="font-black text-xs uppercase tracking-widest text-slate-400 mb-6 flex items-center gap-2"><Settings size={14} /> Page Loop Strategy</h3>
                            <div className="space-y-5">
                                <div>
                                    <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Identify Pages By</label>
                                    <select 
                                        value={pageStrategy.mode} 
                                        onChange={(e) => setPageStrategy({...pageStrategy, mode: e.target.value})}
                                        className="w-full mt-1 bg-slate-50 border border-slate-200 rounded-xl p-3 text-sm font-bold outline-none"
                                    >
                                        <option value="all">Apply to All Pages</option>
                                        <option value="regex">Identify by Regex Match</option>
                                        <option value="first">Template Page Only (Page 1)</option>
                                    </select>
                                </div>
                                {pageStrategy.mode === 'regex' && (
                                    <div>
                                        <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Regex Match Filter</label>
                                        <input 
                                            type="text" 
                                            placeholder="e.g. Data entrata.*" 
                                            value={pageStrategy.regex}
                                            onChange={(e) => setPageStrategy({...pageStrategy, regex: e.target.value})}
                                            className="w-full mt-1 bg-slate-50 border border-slate-200 rounded-xl p-3 text-sm font-mono outline-none"
                                        />
                                    </div>
                                )}
                                <div>
                                    <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Loop Break Condition</label>
                                    <input 
                                        type="text" 
                                        placeholder="e.g. Totale Netto" 
                                        value={pageStrategy.stopCondition}
                                        onChange={(e) => setPageStrategy({...pageStrategy, stopCondition: e.target.value})}
                                        className="w-full mt-1 bg-slate-50 border border-slate-200 rounded-xl p-3 text-sm font-bold outline-none"
                                    />
                                    <p className="text-[9px] text-slate-400 mt-2 px-1 leading-tight">If this text is found on a page, the parser stops processing subsequent lines/pages.</p>
                                </div>
                            </div>
                        </div>
                    )}
                </div>

                {/* Output JSON (Result) */}
                {Object.keys(previewData).length > 0 && (
                    <div className="bg-slate-900 rounded-3xl p-6 shadow-2xl overflow-hidden border border-white/5 text-left">
                        <div className="flex justify-between items-center mb-4">
                            <h4 className="text-[10px] font-black uppercase tracking-[0.2em] text-white/40">Extraction Preview</h4>
                            <span className="text-[9px] font-bold text-emerald-400 flex items-center gap-1"><CheckCircle2 size={10} /> Valid JSON</span>
                        </div>
                        <div className="max-h-80 overflow-y-auto custom-scrollbar">
                            <pre className="text-[10px] font-mono text-emerald-500/90 whitespace-pre-wrap leading-relaxed">
                                {JSON.stringify(previewData, null, 2)}
                            </pre>
                        </div>
                    </div>
                )}
            </div>

            {/* Canvas Area (MAIN) */}
            <div className="lg:col-span-2 bg-slate-100 rounded-[40px] min-h-[850px] flex flex-col items-center justify-center border border-slate-200 relative overflow-hidden shadow-inner p-10 select-none">

                {/* Visual Status Legend */}
                <div className="absolute top-6 left-10 flex gap-6 z-40 bg-white/80 backdrop-blur-md px-4 py-2 rounded-full border border-slate-100 shadow-sm text-[9px] font-black uppercase tracking-widest text-slate-500">
                    <div className="flex items-center gap-2"><div className="w-2 h-2 rounded-full bg-emerald-500"></div> Table</div>
                    <div className="flex items-center gap-2"><div className="w-2 h-2 rounded-full bg-rose-500"></div> Text</div>
                    <div className="flex items-center gap-2"><div className="w-2 h-2 rounded-full bg-blue-500"></div> Key-Value</div>
                </div>

                <div 
                    ref={canvasRef}
                    className="bg-white shadow-2xl relative cursor-crosshair transition-all border border-slate-100 rounded-sm"
                    style={{ width: '595px', height: '842px' }} 
                    onMouseDown={handleMouseDown}
                    onMouseMove={handleMouseMove}
                    onMouseUp={handleMouseUp}
                    onMouseLeave={handleMouseLeave}
                >
                    {/* The actual Document Image */}
                    {debugImage ? (
                        <img 
                            src={`data:image/png;base64,${debugImage}`} 
                            className="absolute inset-0 w-full h-full object-fill pointer-events-none" 
                            alt="PDF Preview"
                        />
                    ) : (
                        <div className="absolute inset-0 flex flex-col items-center justify-center text-slate-300 p-10 text-center">
                            <MousePointer2 size={48} className="mb-4 opacity-20" />
                            <p className="font-black uppercase tracking-widest text-sm mb-2">Editor Ready</p>
                            <p className="text-xs font-medium max-w-[200px]">Upload a sample document to visualize and test your regions.</p>
                        </div>
                    )}

                    {/* Drawn Region Boxes */}
                    {regions.map((r) => (
                        <div
                            key={r.id}
                            className={`absolute border-2 region-box group transition-all ${selectedRegionId === r.id ? 'border-primary-start bg-primary-start/10 z-30 shadow-brand' : 'border-slate-400/40 hover:border-slate-600 bg-white/5 z-20 shadow-sm'}`}
                            style={{
                                left: `${r.x}%`,
                                top: `${r.y}%`,
                                width: `${r.w}%`,
                                height: `${r.h}%`
                            }}
                            onClick={(e) => {
                                e.stopPropagation();
                                setSelectedRegionId(r.id);
                            }}
                        >
                            {/* Label Tag Overlay */}
                            <div className={`absolute -top-7 left-0 px-3 py-1 rounded-t-lg text-[9px] font-black uppercase tracking-widest text-white whitespace-nowrap shadow-md transform transition-transform ${selectedRegionId === r.id ? 'bg-primary-start scale-105' : 'bg-slate-600'}`}>
                                {r.name}
                            </div>

                            {/* Table Column Grid Lines */}
                            {r.type === 'table' && r.columns?.map((col, i) => {
                                const regionStart = (r.x / 100) * 595;
                                const relLeft = col.x - regionStart;
                                return (
                                    <div 
                                        key={i}
                                        className="absolute top-0 bottom-0 border-l border-dashed border-purple-500/80"
                                        style={{ left: `${relLeft}px` }} 
                                    ></div>
                                );
                            })}
                        </div>
                    ))}

                    {/* Visual Preview of region being dragged/drawn */}
                    {isDrawing && (
                        <div 
                            className="absolute border-2 border-dashed border-emerald-500 bg-emerald-500/10 pointer-events-none z-50 rounded-sm"
                            style={{
                                left: currentRect.x,
                                top: currentRect.y,
                                width: currentRect.w,
                                height: currentRect.h
                            }}
                        ></div>
                    )}
                </div>

                <div className="mt-8 text-center">
                    <p className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 flex items-center justify-center gap-2">
                        <AlertCircle size={12} /> Pro Tip: Drag your mouse to define an extraction zone
                    </p>
                </div>
             </div>
          </div>
        )}
      </div>
    </div>
  );
};

