import React, { useState, useRef, useEffect } from 'react';
import { 
  X, Save, Play, Plus, Trash2, Settings, FileText, 
  Table as TableIcon, ChevronLeft, ChevronRight, 
  MousePointer2, List as ListIcon, Edit, Layers,
  CheckCircle2, AlertCircle, ArrowUp, ArrowDown,
  GitBranch
} from 'lucide-react';
import axios from 'axios';

interface ParserBuilderProps {
  onClose: () => void;
  apiBaseUrl: string;
}

type RegionType = 'table' | 'text' | 'key_value';
type ColumnType = 'string' | 'currency' | 'float' | 'date';

interface ColumnDef {
  x: number; 
  name: string;
  type: ColumnType;
}

interface Region {
  id: string;
  x: number; // %
  y: number; // %
  w: number; // %
  h: number; // %
  type: RegionType;
  name: string;
  key_label?: string; // For key_value type
  columns?: ColumnDef[];
}

interface Transition {
  id: string;
  condition: 'regex' | 'text' | 'index' | 'always' | 'stop';
  value: string;
  action: 'next_stage' | 'next_template';
  targetId: string;
}

interface Stage {
  id: string;
  name: string;
  regions: Region[];
  transitions: Transition[];
}

export const ParserBuilder: React.FC<ParserBuilderProps> = ({ onClose, apiBaseUrl }) => {
  // View State
  const [view, setView] = useState<'list' | 'edit'>('list');
  const [editTab, setEditTab] = useState<'layout' | 'flow'>('layout');
  const [templates, setTemplates] = useState<any[]>([]);

  // Template State
  const [templateId, setTemplateId] = useState<string | null>(null);
  const [templateName, setTemplateName] = useState('');

  // Multi-Stage State
  const [stages, setStages] = useState<Stage[]>([]);
  const [activeStageId, setActiveStageId] = useState<string | null>(null);
  const [selectedRegionId, setSelectedRegionId] = useState<string | null>(null);

  // Page Navigation
  const [currentPage, setCurrentPage] = useState(0);
  const [pageCount, setPageCount] = useState(1);

  // Data Preview
  const [testFile, setTestFile] = useState<File | null>(null);
  const [previewData, setPreviewData] = useState<any>({});
  const [debugImage, setDebugImage] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);

  // Drawing State
  const canvasRef = useRef<HTMLDivElement>(null);
  const [isDrawing, setIsDrawing] = useState(false);
  const [startPos, setStartPos] = useState({ x: 0, y: 0 });
  const [currentRect, setCurrentRect] = useState({ x: 0, y: 0, w: 0, h: 0 });

  // Get active stage helper
  const activeStage = stages.find(s => s.id === activeStageId) || stages[0];
  const regions = activeStage?.regions || [];

  // -------------------------------------------------------------------------
  // Template Management
  // -------------------------------------------------------------------------
  useEffect(() => {
      if (view === 'list') fetchTemplates();
  }, [view]);

  const fetchTemplates = async () => {
      try {
          const res = await axios.get(`${apiBaseUrl}/api/parsers/templates`);
          setTemplates(res.data);
      } catch (err) {
          console.error("Failed to load templates");
      }
  };

  const handleSaveTemplate = async () => {
      if (!templateName.trim()) {
          alert("Please name your template.");
          return;
      }

      try {
          const payload = {
              id: templateId,
              name: templateName,
              stages: stages,
              start_stage_id: stages[0]?.id
          };

          await axios.post(`${apiBaseUrl}/api/parsers/templates`, payload);
          alert("Template saved!");
          fetchTemplates();
          setView('list');
      } catch (error) {
          alert("Failed to save template.");
      }
  };

  const handleEditTemplate = (tmpl: any) => {
      setTemplateId(tmpl.id);
      setTemplateName(tmpl.name);

      if (tmpl.stages) {
          setStages(tmpl.stages);
          setActiveStageId(tmpl.start_stage_id || tmpl.stages[0]?.id);
      } else {
          const legacyStage: Stage = {
              id: 'default',
              name: 'Main Stage',
              regions: tmpl.regions || [],
              transitions: []
          };
          setStages([legacyStage]);
          setActiveStageId('default');
      }

      setTestFile(null);
      setDebugImage(null);
      setPreviewData({});
      setCurrentPage(0);
      setView('edit');
      setEditTab('layout');
  };

  const handleDeleteTemplate = async (id: string) => {
      if (!window.confirm("Are you sure?")) return;
      try {
          await axios.delete(`${apiBaseUrl}/api/parsers/templates/${id}`);
          fetchTemplates();
      } catch (err) {
          alert("Delete failed.");
      }
  };

  const handleNewTemplate = () => {
      const initialStage: Stage = {
          id: Math.random().toString(36).substr(2, 9),
          name: "Start Stage",
          regions: [],
          transitions: []
      };
      setTemplateId(null);
      setTemplateName("New Template");
      setStages([initialStage]);
      setActiveStageId(initialStage.id);
      setTestFile(null);
      setDebugImage(null);
      setPreviewData({});
      setView('edit');
      setEditTab('layout');
  };

  // -------------------------------------------------------------------------
  // Stage Management
  // -------------------------------------------------------------------------
  const addStage = () => {
      const newStage: Stage = {
          id: Math.random().toString(36).substr(2, 9),
          name: `Stage ${stages.length + 1}`,
          regions: [],
          transitions: []
      };
      setStages([...stages, newStage]);
      setActiveStageId(newStage.id);
  };

  const updateActiveStage = (updates: Partial<Stage>) => {
      setStages(stages.map(s => s.id === activeStageId ? { ...s, ...updates } : s));
  };

  const deleteStage = (id: string) => {
      if (stages.length <= 1) return alert("Templates must have at least one stage.");
      const nextStages = stages.filter(s => s.id !== id);
      setStages(nextStages);
      if (activeStageId === id) setActiveStageId(nextStages[0].id);
  };

  const addTransition = () => {
      if (!activeStage) return;
      const newTransition: Transition = {
          id: Math.random().toString(36).substr(2, 9),
          condition: 'always',
          value: '',
          action: 'next_stage',
          targetId: ''
      };
      updateActiveStage({ transitions: [...(activeStage.transitions || []), newTransition] });
  };

  const updateTransition = (id: string, updates: Partial<Transition>) => {
      if (!activeStage) return;
      const newTransitions = activeStage.transitions.map(t => t.id === id ? { ...t, ...updates } : t);
      updateActiveStage({ transitions: newTransitions });
  };

  const deleteTransition = (id: string) => {
      if (!activeStage) return;
      updateActiveStage({ transitions: activeStage.transitions.filter(t => t.id !== id) });
  };

  // -------------------------------------------------------------------------
  // Drawing Logic
  // -------------------------------------------------------------------------
  const handleMouseDown = (e: React.MouseEvent) => {
    if (!canvasRef.current || editTab !== 'layout') return;
    if ((e.target as HTMLElement).closest('.region-box')) return;

    const rect = canvasRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    setIsDrawing(true);
    setStartPos({ x, y });
    setCurrentRect({ x, y, w: 0, h: 0 });
    setSelectedRegionId(null); 
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDrawing || !canvasRef.current) return;
    const rect = canvasRef.current.getBoundingClientRect();
    const currentX = e.clientX - rect.left;
    const currentY = e.clientY - rect.top;

    const width = currentX - startPos.x;
    const height = currentY - startPos.y;

    setCurrentRect({
        x: width > 0 ? startPos.x : currentX,
        y: height > 0 ? startPos.y : currentY,
        w: Math.abs(width),
        h: Math.abs(height)
    });
  };

  const handleMouseUp = () => {
    if (!isDrawing || !canvasRef.current) return;
    setIsDrawing(false);

    if (currentRect.w < 10 || currentRect.h < 10) {
        setCurrentRect({ x: 0, y: 0, w: 0, h: 0 });
        return;
    }

    const containerW = canvasRef.current.offsetWidth;
    const containerH = canvasRef.current.offsetHeight;

    const newRegion: Region = {
        id: Math.random().toString(36).substr(2, 9),
        x: (currentRect.x / containerW) * 100,
        y: (currentRect.y / containerH) * 100,
        w: (currentRect.w / containerW) * 100,
        h: (currentRect.h / containerH) * 100,
        type: 'text',
        name: `Region ${regions.length + 1}`,
        columns: []
    };

    updateActiveStage({ regions: [...regions, newRegion] });
    setSelectedRegionId(newRegion.id);
    setCurrentRect({ x: 0, y: 0, w: 0, h: 0 });
  };

  const handleMouseLeave = () => {
      if (isDrawing) {
          setIsDrawing(false);
          setCurrentRect({ x: 0, y: 0, w: 0, h: 0 });
      }
  };

  // -------------------------------------------------------------------------
  // Region Editing Logic
  // -------------------------------------------------------------------------
  const selectedRegion = regions.find(r => r.id === selectedRegionId);

  const updateRegion = (field: keyof Region, value: any) => {
      if (!selectedRegion) return;
      const updatedRegions = regions.map(r => r.id === selectedRegionId ? { ...r, [field]: value } : r);
      updateActiveStage({ regions: updatedRegions });
  };

  const deleteRegion = (id?: string) => {
      const targetId = id || selectedRegionId;
      if (!targetId) return;
      updateActiveStage({ regions: regions.filter(r => r.id !== targetId) });
      if (targetId === selectedRegionId) setSelectedRegionId(null);
  };

  const moveRegion = (index: number, direction: 'up' | 'down') => {
      const newRegions = [...regions];
      if (direction === 'up' && index > 0) {
          [newRegions[index], newRegions[index - 1]] = [newRegions[index - 1], newRegions[index]];
      } else if (direction === 'down' && index < newRegions.length - 1) {
          [newRegions[index], newRegions[index + 1]] = [newRegions[index + 1], newRegions[index]];
      }
      updateActiveStage({ regions: newRegions });
  };

  const addColumn = () => {
      if (!selectedRegion) return;
      const cols = selectedRegion.columns || [];
      const newCol: ColumnDef = { x: 50, name: `Col ${cols.length + 1}`, type: 'string' };
      updateRegion('columns', [...cols, newCol]);
  };

  const updateColumn = (idx: number, field: keyof ColumnDef, val: any) => {
      if (!selectedRegion?.columns) return;
      const newCols = [...selectedRegion.columns];
      newCols[idx] = { ...newCols[idx], [field]: val };
      updateRegion('columns', newCols);
  };

  const removeColumn = (idx: number) => {
      if (!selectedRegion?.columns) return;
      updateRegion('columns', selectedRegion.columns.filter((_, i) => i !== idx));
  };

  const handleTestExtraction = async () => {
    if (!testFile) return alert("Please upload a sample file.");
    setIsLoading(true);
    const formData = new FormData();
    formData.append('file', testFile);
    formData.append('page', currentPage.toString());
    formData.append('config', JSON.stringify({ stages, active_stage_id: activeStageId }));
    try {
        const res = await axios.post(`${apiBaseUrl}/api/parsers/preview`, formData);
        setPreviewData(res.data.extracted_data);
        setDebugImage(res.data.debug_image);
        if (res.data.page_count) setPageCount(res.data.page_count);
    } catch (err) { alert("Extraction failed"); } finally { setIsLoading(false); }
  };

  return (
    <div className="fixed inset-0 bg-canvas z-50 overflow-y-auto font-sans">
      <div className="max-w-7xl mx-auto p-8 text-left">

        {/* Main Header */}
        <div className="flex justify-between items-center mb-8">
          <div className="flex items-center gap-4">
            {view === 'edit' && (
                <button onClick={() => setView('list')} className="p-2 bg-white rounded-full shadow-sm hover:bg-slate-50 transition-colors">
                    <ChevronLeft size={20} />
                </button>
            )}
            <div>
                <h1 className="text-3xl font-bold tracking-tight text-slate-900">Parser Builder</h1>
                <p className="text-slate-500 font-medium">
                    {view === 'list' ? 'Manage your extraction templates.' : 'Design and test your extraction layout.'}
                </p>
            </div>
          </div>
          <div className="flex gap-4">
            {view === 'edit' && (
                <div className="flex items-center gap-1 bg-slate-100 p-1 rounded-xl">
                    <button onClick={() => setEditTab('layout')} className={`px-4 py-2 rounded-lg text-xs font-black uppercase tracking-widest transition-all ${editTab === 'layout' ? 'bg-white shadow-sm text-primary-start' : 'text-slate-400'}`}>Layout</button>
                    <button onClick={() => setEditTab('flow')} className={`px-4 py-2 rounded-lg text-xs font-black uppercase tracking-widest transition-all ${editTab === 'flow' ? 'bg-white shadow-sm text-primary-start' : 'text-slate-400'}`}>Flow</button>
                </div>
            )}
            {view === 'edit' && (
                <div className="flex items-center gap-3 bg-white px-4 py-2 rounded-xl shadow-sm border border-slate-100">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Template Name</span>
                    <input type="text" value={templateName} onChange={(e) => setTemplateName(e.target.value)} className="font-bold text-slate-800 outline-none w-48 bg-transparent" placeholder="e.g. My Invoice" />
                </div>
            )}
            {view === 'edit' && (
                <button onClick={handleSaveTemplate} className="flex items-center gap-2 px-6 py-2 bg-slate-900 text-white rounded-xl font-bold hover:scale-105 transition-transform shadow-lg"><Save size={18} /> Save</button>
            )}
            <button onClick={onClose} className="p-2 hover:bg-slate-200 rounded-full transition-colors"><X size={24} /></button>
          </div>
        </div>

        {/* LIST VIEW */}
        {view === 'list' && (
            <div className="bg-surface rounded-[40px] shadow-soft p-10 border border-slate-100">
                <div className="flex justify-between items-center mb-10">
                    <div><h3 className="text-2xl font-black tracking-tight">Saved Templates</h3><p className="text-slate-400 text-sm font-medium">Select a template to edit.</p></div>
                    <button onClick={handleNewTemplate} className="flex items-center gap-2 px-8 py-4 bg-primary-start text-white font-black rounded-2xl hover:bg-primary-end transition-all shadow-brand hover:scale-105"><Plus size={20} /> New Template</button>
                </div>
                {templates.length === 0 ? (
                    <div className="text-center py-24 bg-slate-50 rounded-[32px] border-2 border-dashed border-slate-200 text-slate-300"><ListIcon size={64} className="mx-auto mb-6 opacity-20" /><p className="font-bold text-lg">No templates found.</p></div>
                ) : (
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                        {templates.map(t => (
                            <div key={t.id} className="bg-white p-8 rounded-[32px] border border-slate-100 shadow-sm hover:shadow-xl transition-all group relative overflow-hidden">
                                <div className="relative z-10">
                                    <div className="flex justify-between items-start mb-6">
                                        <div className="p-4 bg-slate-50 rounded-2xl text-slate-400 group-hover:text-primary-start group-hover:bg-primary-start/10 transition-colors"><FileText size={28} /></div>
                                        <div className="flex gap-2">
                                            <button onClick={() => handleEditTemplate(t)} className="p-2 text-slate-400 hover:text-emerald-600 hover:bg-emerald-50 rounded-lg transition-colors"><Edit size={18} /></button>
                                            <button onClick={() => handleDeleteTemplate(t.id)} className="p-2 text-slate-400 hover:text-rose-600 hover:bg-rose-50 rounded-lg transition-colors"><Trash2 size={18} /></button>
                                        </div>
                                    </div>
                                    <h4 className="font-black text-xl mb-2 text-slate-800">{t.name}</h4>
                                    <p className="text-[10px] font-black uppercase tracking-widest text-slate-400">{t.stages?.length || 1} Stages</p>
                                </div>
                            </div>
                        ))}
                    </div>
                )}
            </div>
        )}

        {/* EDITOR TABS AREA */}
        {view === 'edit' && (
            <>
                {/* Global Stage Selector */}
                <div className="flex items-center gap-4 mb-8 bg-surface p-4 rounded-3xl border border-slate-100 shadow-soft">
                    <div className="flex items-center gap-2 px-4 border-r border-slate-100 text-slate-400 uppercase font-black text-[10px] tracking-widest">Active Stage</div>
                    <div className="flex flex-wrap gap-2">
                        {stages.map(s => (
                            <button key={s.id} onClick={() => setActiveStageId(s.id)} className={`px-4 py-2 rounded-xl text-xs font-bold transition-all border ${activeStageId === s.id ? 'bg-primary-start border-primary-start text-white shadow-brand' : 'bg-slate-50 border-slate-100 text-slate-500 hover:border-slate-300'}`}>{s.name}</button>
                        ))}
                        <button onClick={addStage} className="p-2 rounded-xl bg-emerald-50 text-emerald-600 hover:bg-emerald-100 transition-colors border border-emerald-100"><Plus size={16} /></button>
                    </div>
                </div>

                {editTab === 'layout' ? (
                    <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 items-start">
                        {/* Sidebar */}
                        <div className="lg:col-span-1 space-y-6">
                            <div className="bg-surface p-6 rounded-3xl shadow-soft border border-slate-100">
                                <h3 className="font-black text-xs uppercase tracking-widest text-slate-400 mb-4 flex items-center gap-2"><FileText size={14} /> Sample Source</h3>
                                <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100 text-center">
                                    <input type="file" id="sample-up" className="hidden" onChange={(e) => { setTestFile(e.target.files ? e.target.files[0] : null); setDebugImage(null); }} />
                                    <label htmlFor="sample-up" className="cursor-pointer block"><p className="text-sm font-bold text-slate-700 truncate">{testFile ? testFile.name : 'Choose file...'}</p></label>
                                </div>
                                {testFile && (
                                    <div className="flex items-center justify-between mt-4 bg-slate-900 text-white p-2 rounded-2xl">
                                        <button onClick={() => setCurrentPage(Math.max(0, currentPage - 1))} className="p-2 hover:bg-white/10 rounded-xl"><ChevronLeft size={20} /></button>
                                        <div className="text-center font-mono text-sm">{currentPage + 1} / {pageCount}</div>
                                        <button onClick={() => setCurrentPage(Math.min(pageCount - 1, currentPage + 1))} className="p-2 hover:bg-white/10 rounded-xl"><ChevronRight size={20} /></button>
                                    </div>
                                )}
                                <button onClick={handleTestExtraction} disabled={!testFile || isLoading} className={`w-full mt-4 py-4 font-black rounded-2xl flex items-center justify-center gap-2 transition-all shadow-brand ${!testFile ? 'bg-slate-100 text-slate-300' : 'bg-primary-start text-white hover:scale-[1.02]'}`}>
                                    {isLoading ? <span className="animate-spin text-lg">⟳</span> : <Play size={18} fill="currentColor" />} {isLoading ? 'Processing...' : 'Run Extraction'}
                                </button>
                            </div>

                            <div className="bg-surface p-6 rounded-3xl shadow-soft border border-slate-100">
                                <h3 className="font-black text-xs uppercase tracking-widest text-slate-400 mb-4 flex items-center gap-2"><Layers size={14} /> Layout Zones</h3>
                                <div className="space-y-2 max-h-48 overflow-y-auto pr-1">
                                    {regions.map((r, idx) => (
                                        <div key={r.id} onClick={() => setSelectedRegionId(r.id)} className={`flex items-center justify-between p-3 rounded-xl border transition-all cursor-pointer ${selectedRegionId === r.id ? 'bg-primary-start/5 border-primary-start/30 shadow-sm' : 'bg-white border-slate-100'}`}>
                                            <div className="flex items-center gap-3"><div className={`w-2 h-2 rounded-full ${r.type === 'table' ? 'bg-emerald-500' : r.type === 'text' ? 'bg-rose-500' : 'bg-blue-500'}`}></div><span className="text-xs font-bold text-slate-700 truncate max-w-[80px]">{r.name}</span></div>
                                            <div className="flex items-center gap-1">
                                                <button onClick={(e) => { e.stopPropagation(); moveRegion(idx, 'up'); }} className="text-slate-300 hover:text-slate-600 p-1"><ArrowUp size={12} /></button>
                                                <button onClick={(e) => { e.stopPropagation(); moveRegion(idx, 'down'); }} className="text-slate-300 hover:text-slate-600 p-1"><ArrowDown size={12} /></button>
                                                <button onClick={(e) => { e.stopPropagation(); deleteRegion(r.id); }} className="text-slate-300 hover:text-rose-500 ml-1"><Trash2 size={14} /></button>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </div>

                            {selectedRegion && (
                                <div className="bg-surface p-6 rounded-3xl shadow-soft border-2 border-primary-start animate-in slide-in-from-left-2">
                                    <div className="flex justify-between items-center mb-6"><h3 className="font-black text-xs uppercase text-primary-start flex items-center gap-2"><MousePointer2 size={14} /> Configure</h3><button onClick={() => setSelectedRegionId(null)} className="text-slate-400"><X size={16} /></button></div>
                                    <div className="space-y-5">
                                        <div><label className="text-[10px] font-black uppercase text-slate-400 ml-1">Label</label><input type="text" value={selectedRegion.name} onChange={(e) => updateRegion('name', e.target.value)} className="w-full mt-1 bg-slate-50 border border-slate-200 rounded-xl p-3 text-sm font-bold outline-none focus:border-primary-start" /></div>
                                        {selectedRegion.type === 'key_value' && (
                                            <div><label className="text-[10px] font-black uppercase text-slate-400 ml-1">Key Label</label><input type="text" value={selectedRegion.key_label || ''} onChange={(e) => updateRegion('key_label', e.target.value)} placeholder="e.g. IBAN" className="w-full mt-1 bg-slate-50 border border-slate-200 rounded-xl p-3 text-sm font-bold outline-none focus:border-primary-start" /></div>
                                        )}
                                        <div><label className="text-[10px] font-black uppercase text-slate-400 ml-1">Type</label><select value={selectedRegion.type} onChange={(e) => updateRegion('type', e.target.value)} className="w-full mt-1 bg-slate-50 border border-slate-200 rounded-xl p-3 text-sm font-bold outline-none"><option value="text">Raw Text</option><option value="table">Table</option><option value="key_value">Key-Value</option></select></div>
                                        {selectedRegion.type === 'table' && (
                                            <div className="border-t border-slate-100 pt-5"><div className="flex justify-between items-center mb-3"><label className="text-[10px] font-black uppercase text-slate-400 ml-1">Columns</label><button onClick={addColumn} className="text-[10px] font-black text-emerald-600 uppercase tracking-tighter hover:underline">+ Add</button></div>
                                                <div className="space-y-3 max-h-60 overflow-y-auto pr-1">
                                                    {(selectedRegion.columns || []).map((col, idx) => (
                                                        <div key={idx} className="bg-white p-3 rounded-2xl border border-slate-100 shadow-sm space-y-2"><div className="flex gap-2"><input type="number" value={col.x} onChange={(e) => updateColumn(idx, 'x', parseInt(e.target.value))} className="w-16 bg-slate-50 border border-slate-100 rounded-lg p-1.5 text-[10px] font-mono font-bold" /><input type="text" value={col.name} onChange={(e) => updateColumn(idx, 'name', e.target.value)} className="flex-1 bg-slate-50 border border-slate-100 rounded-lg p-1.5 text-[10px] font-bold" /><button onClick={() => removeColumn(idx)} className="text-slate-300 hover:text-rose-500"><Trash2 size={14} /></button></div><select value={col.type} onChange={(e) => updateColumn(idx, 'type', e.target.value)} className="w-full bg-slate-50 border border-slate-100 rounded-lg p-1.5 text-[9px] font-black uppercase text-slate-500"><option value="string">String</option><option value="currency">Currency</option><option value="float">Float</option><option value="date">Date</option></select></div>
                                                    ))}
                                                </div>
                                            </div>
                                        )}
                                    </div>
                                </div>
                            )}
                            {Object.keys(previewData).length > 0 && (
                                <div className="bg-slate-900 rounded-3xl p-6 shadow-2xl overflow-hidden border border-white/5"><h4 className="text-[10px] font-black uppercase tracking-[0.2em] text-white/40 mb-4">Preview</h4><div className="max-h-80 overflow-y-auto custom-scrollbar"><pre className="text-[10px] font-mono text-emerald-500/90 whitespace-pre-wrap">{JSON.stringify(previewData, null, 2)}</pre></div></div>
                            )}
                        </div>

                        {/* Canvas */}
                        <div className="lg:col-span-2 bg-slate-100 rounded-[40px] min-h-[850px] flex flex-col items-center justify-center border border-slate-200 relative overflow-hidden shadow-inner p-10 select-none">
                            <div className="absolute top-6 left-10 flex gap-6 z-40 bg-white/80 backdrop-blur-md px-4 py-2 rounded-full border border-slate-100 shadow-sm text-[9px] font-black uppercase text-slate-500"><div className="flex items-center gap-2"><div className="w-2 h-2 rounded-full bg-emerald-500"></div> Table</div><div className="flex items-center gap-2"><div className="w-2 h-2 rounded-full bg-rose-500"></div> Text</div><div className="flex items-center gap-2"><div className="w-2 h-2 rounded-full bg-blue-500"></div> KV</div></div>
                            <div ref={canvasRef} className="bg-white shadow-2xl relative cursor-crosshair transition-all border border-slate-100 rounded-sm" style={{ width: '595px', height: '842px' }} onMouseDown={handleMouseDown} onMouseMove={handleMouseMove} onMouseUp={handleMouseUp} onMouseLeave={handleMouseLeave}>
                                {debugImage ? <img src={`data:image/png;base64,${debugImage}`} className="absolute inset-0 w-full h-full object-fill pointer-events-none" alt="PDF" /> : <div className="absolute inset-0 flex flex-col items-center justify-center text-slate-300 p-10 text-center"><MousePointer2 size={48} className="mb-4 opacity-20" /><p className="font-black uppercase tracking-widest text-sm mb-2">Canvas Ready</p></div>}
                                {regions.map((r) => (
                                    <div key={r.id} className={`absolute border-2 region-box group transition-all ${selectedRegionId === r.id ? 'border-primary-start bg-primary-start/10 z-30 shadow-brand' : 'border-slate-400/40 bg-white/5 z-20'}`} style={{ left: `${r.x}%`, top: `${r.y}%`, width: `${r.w}%`, height: `${r.h}%` }} onClick={(e) => { e.stopPropagation(); setSelectedRegionId(r.id); }}>
                                        <div className={`absolute -top-7 left-0 px-3 py-1 rounded-t-lg text-[9px] font-black uppercase tracking-widest text-white shadow-md transform transition-transform ${selectedRegionId === r.id ? 'bg-primary-start scale-105' : 'bg-slate-600'}`}>{r.name}</div>
                                        {r.type === 'table' && r.columns?.map((col, i) => {
                                            const regionStart = (r.x / 100) * 595;
                                            const relLeft = col.x - regionStart;
                                            return (
                                                <React.Fragment key={i}><div className="absolute top-0 bottom-0 border-l border-dashed border-purple-500/80" style={{ left: `${relLeft}px` }} /><div className="absolute -top-4 text-[8px] font-bold text-purple-600 whitespace-nowrap bg-white/90 px-1 rounded shadow-sm" style={{ left: `${relLeft}px`, transform: 'translateX(-50%)' }}>{col.name}</div></React.Fragment>
                                            );
                                        })}
                                        {r.type === 'key_value' && r.key_label && (<div className="absolute inset-0 flex items-center justify-center pointer-events-none"><span className="bg-blue-500/20 text-blue-700 text-[10px] font-black uppercase px-2 py-0.5 rounded-full border border-blue-500/30">Key: {r.key_label}</span></div>)}
                                    </div>
                                ))}
                                {isDrawing && (<div className="absolute border-2 border-dashed border-emerald-500 bg-emerald-500/10 pointer-events-none z-50 rounded-sm" style={{ left: currentRect.x, top: currentRect.y, width: currentRect.w, height: currentRect.h }} />)}
                            </div>
                            <div className="mt-8 text-center text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 flex items-center justify-center gap-2"><AlertCircle size={12} /> Drag mouse to define zones</div>
                        </div>
                    </div>
                ) : (
                    /* Flow Editor */
                    <div className="bg-surface rounded-[40px] shadow-soft p-10 border border-slate-100 min-h-[600px]">
                        <div className="grid grid-cols-1 lg:grid-cols-4 gap-10">
                            <div className="lg:col-span-1 border-r border-slate-100 pr-10">
                                <h3 className="font-black text-xs uppercase tracking-widest text-slate-400 mb-6 flex items-center gap-2"><Layers size={14} /> Parsing Stages</h3>
                                <div className="space-y-3">
                                    {stages.map(s => (
                                        <div key={s.id} onClick={() => setActiveStageId(s.id)} className={`group flex items-center justify-between p-4 rounded-2xl border transition-all cursor-pointer ${activeStageId === s.id ? 'bg-primary-start border-primary-start text-white shadow-brand' : 'bg-white border-slate-100 hover:border-slate-300'}`}>
                                            <div><p className={`text-[8px] font-black uppercase tracking-widest ${activeStageId === s.id ? 'text-white/60' : 'text-slate-400'}`}>Stage Name</p><input type="text" value={s.name} onChange={(e) => updateActiveStage({ name: e.target.value })} onClick={(e) => e.stopPropagation()} className={`bg-transparent font-bold outline-none w-full ${activeStageId === s.id ? 'text-white' : 'text-slate-800'}`} /></div>
                                            <button onClick={(e) => { e.stopPropagation(); deleteStage(s.id); }} className={`${activeStageId === s.id ? 'text-white/40 hover:text-white' : 'text-slate-200 hover:text-rose-500'}`}><Trash2 size={16} /></button>
                                        </div>
                                    ))}
                                    <button onClick={addStage} className="w-full py-4 rounded-2xl border-2 border-dashed border-slate-200 text-slate-400 font-bold text-sm hover:border-primary-start transition-all">+ Add Stage</button>
                                </div>
                            </div>
                            <div className="lg:col-span-3">
                                <div className="flex justify-between items-center mb-10"><div><h2 className="text-2xl font-black text-slate-800">Transitions for "{activeStage?.name}"</h2><p className="text-slate-400 text-sm font-medium mt-1">Conditional branching logic (If/Then).</p></div><button onClick={addTransition} className="flex items-center gap-2 px-6 py-3 bg-slate-900 text-white rounded-xl font-bold shadow-lg"><GitBranch size={18} /> Add Transition</button></div>
                                <div className="space-y-6">
                                    {(activeStage?.transitions || []).map((t, idx) => (
                                        <div key={t.id} className="bg-slate-50 rounded-3xl p-8 border border-slate-100 flex flex-col md:flex-row items-center gap-6 relative group animate-in slide-in-from-right-4"><div className="absolute -left-3 top-1/2 -translate-y-1/2 w-6 h-6 rounded-full bg-slate-900 text-white flex items-center justify-center text-[10px] font-black">{idx + 1}</div>
                                            <div className="flex-1 space-y-4">
                                                <div className="flex items-center gap-4"><span className="text-[10px] font-black uppercase text-slate-400 tracking-widest">If</span><select value={t.condition} onChange={(e) => updateTransition(t.id, { condition: e.target.value as any })} className="bg-white border border-slate-200 rounded-xl px-4 py-2 text-sm font-bold outline-none"><option value="always">Always</option><option value="regex">Regex Match</option><option value="text">Contains Text</option><option value="index">Page Index</option><option value="stop">Stop Processing</option></select>
                                                {t.condition !== 'always' && t.condition !== 'stop' && <input type="text" placeholder="Value..." value={t.value} onChange={(e) => updateTransition(t.id, { value: e.target.value })} className="flex-1 bg-white border border-slate-200 rounded-xl px-4 py-2 text-sm font-mono outline-none" />}</div>
                                                <div className="flex items-center gap-4"><span className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Then</span><select value={t.action} onChange={(e) => updateTransition(t.id, { action: e.target.value as any })} className="bg-white border border-slate-200 rounded-xl px-4 py-2 text-sm font-bold outline-none"><option value="next_stage">Go to Stage</option><option value="next_template">Switch Template</option></select>
                                                {t.action === 'next_stage' ? <select value={t.targetId} onChange={(e) => updateTransition(t.id, { targetId: e.target.value })} className="flex-1 bg-white border border-slate-200 rounded-xl px-4 py-2 text-sm font-bold outline-none text-primary-start"><option value="">Select Stage...</option>{stages.filter(s => s.id !== activeStage?.id).map(s => <option key={s.id} value={s.id}>{s.name}</option>)}</select> : <select value={t.targetId} onChange={(e) => updateTransition(t.id, { targetId: e.target.value })} className="flex-1 bg-white border border-slate-200 rounded-xl px-4 py-2 text-sm font-bold outline-none text-emerald-600"><option value="">Select Template...</option>{templates.filter(tmpl => tmpl.id !== templateId).map(tmpl => <option key={tmpl.id} value={tmpl.id}>{tmpl.name}</option>)}</select>}</div>
                                            </div>
                                            <button onClick={() => deleteTransition(t.id)} className="p-3 text-slate-300 hover:text-rose-500 transition-colors"><Trash2 size={20} /></button>
