} from 'lucide-react';
import axios from 'axios';

interface ParserBuilderProps {
  onClose: () => void;
  apiBaseUrl: string;
}

type RegionType = 'table' | 'text' | 'key_value';
type ColumnType = 'string' | 'currency' | 'float' | 'date';

interface ColumnDef {
  x: number; // Percentage of page width
  name: string;
  type: ColumnType;
  sign?: 'positive' | 'negative' | 'none';
}

interface KVField {
  id: string;
  name: string;
  x: number; // % relative to parent region
  y: number; // % relative to parent region
  w: number; // %
  h: number; // %
}

interface Region {
  id: string;
  x: number; // %
  y: number; // %
  w: number; // %
  h: number; // %
  type: RegionType;
  name: string;
  key_label?: string; // Legacy
  fields?: KVField[];
  columns?: ColumnDef[];
}

interface Transition {
  id: string;
  condition: 'regex' | 'text' | 'index' | 'always' | 'stop';
  value: string;
  action: 'next_stage' | 'next_template';
  targetId: string;
}

interface Stage {
  id: string;
  name: string;
  regions: Region[];
  transitions: Transition[];
}

